#!/usr/bin/env python3
"""Require complete, passing, non-skipped LMDB JUnit reports in their owning CI jobs."""
# Some portions generated by Codex
from __future__ import annotations

import argparse
import json
import sys
import xml.etree.ElementTree as ET
from pathlib import Path
from typing import Any, Iterable


SUREFIRE_TEST_CLASSES = (
    "LmdbCrashRecoveryTest",
    "LmdbStoreFlushReproductionTest",
    "TripleStoreAutoGrowTest",
    "ValueStoreTermIndexRecoveryTest",
    "LmdbConstructorCleanupTest",
    "PersistentSetFactoryTransactionOwnershipTest",
    "LmdbSnapshotValueLifetimeTest",
    "LmdbValueRetirementRecoveryTest",
    "TxnMutationJournalTest",
)
FAILSAFE_IT_CLASSES = ("LmdbStoreModelLifecycleIT",)


def _require(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


def _local_tag(tag: str) -> str:
    return tag.rsplit("}", 1)[-1]


def _testsuites(root: ET.Element) -> Iterable[ET.Element]:
    for element in root.iter():
        if _local_tag(element.tag) == "testsuite":
            yield element


def _count_attribute(suite: ET.Element, name: str, path: Path) -> int:
    value = suite.get(name)
    _require(value is not None and value.isdigit(), f"{path}: test suite has invalid {name} count")
    return int(value)


def validate_selected_test_reports(kind: str, directory: Path) -> dict[str, Any]:
    totals: dict[str, dict[str, int]] = {}
    selected = (("Surefire", SUREFIRE_TEST_CLASSES) if kind == "unit"
                else ("Failsafe", FAILSAFE_IT_CLASSES))
    for label, required in (selected,):
        _require(directory.is_dir(), f"missing {label} report directory: {directory}")
        reports = sorted(directory.glob("TEST-*.xml"))
        _require(bool(reports), f"{label} produced no JUnit XML reports")
        found: dict[str, dict[str, int]] = {}
        for path in reports:
            try:
                root = ET.parse(path).getroot()
            except (ET.ParseError, OSError) as error:
                raise ValueError(f"cannot parse {label} report {path}: {error}") from error
            for suite in _testsuites(root):
                name = suite.get("name", "").rsplit(".", 1)[-1]
                if name not in required:
                    continue
                _require(name not in found, f"{label} reports selected test class {name} more than once")
                found[name] = {
                    "tests": _count_attribute(suite, "tests", path),
                    "failures": _count_attribute(suite, "failures", path),
                    "errors": _count_attribute(suite, "errors", path),
                    "skipped": _count_attribute(suite, "skipped", path),
                }
                _require(found[name]["tests"] > 0, f"{label} selected test class {name} ran zero tests")
                _require(found[name]["failures"] == 0 and found[name]["errors"] == 0,
                         f"{label} selected test class {name} had failures or errors")
                _require(found[name]["skipped"] == 0, f"{label} selected test class {name} had skipped tests")
        missing = set(required) - set(found)
        _require(not missing, f"{label} did not run selected test classes: " + ", ".join(sorted(missing)))
        totals[label.lower()] = found
    return totals


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--kind", choices=("unit", "integration"), required=True)
    parser.add_argument("--reports-dir", type=Path, required=True)
    args = parser.parse_args()
    try:
        print(json.dumps(validate_selected_test_reports(args.kind, args.reports_dir), indent=2))
        return 0
    except (OSError, ValueError) as error:
        print(f"LMDB Java report gate failed: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
